// The board's behaviour (preview/index.html and the Phase 3 studies page, both generated by design-build/board.mjs).
// Builds the token specimens from window.DESIGN_TOKENS (tokens.js) and runs the toolbar: theme, side by side,
// page or canvas layout (pan, zoom, minimap, keys), motion replay and the Reduce motion toggle, and the Phase 5
// review. Styles come only from var(--token); this file holds no raw sizes or durations.
(function () {
  var D = window.DESIGN_TOKENS;
  var root = document.documentElement, page = document.body.getAttribute('data-page');
  if (!D) {
    // tokens.js is missing or failed: say so on the page instead of rendering empty sections.
    var main = document.getElementById('main'), msg = document.createElement('p');
    msg.className = 'load-error'; msg.setAttribute('role', 'alert');
    msg.textContent = 'tokens.js did not load, so the token sections are empty. Regenerate it with: node design-build/tokens-css.mjs (from the app root: node design-system/design-build/tokens-css.mjs), then reload.';
    if (main) main.prepend(msg);
    D = { tokens: {}, pairings: [] };
  }
  var T = D.tokens;
  function $(id) { return document.getElementById(id); }
  function all(sel, scope) { return Array.prototype.slice.call((scope || document).querySelectorAll(sel)); }
  function el(tag, cls, text) { var e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; }
  // A token or CSS variable name that wraps only after its dots or hyphens (color.<wbr>brand.<wbr>primary), never mid-word; the full name is the tooltip.
  function tok(tag, cls, name, rest) {
    var e = el(tag, cls); e.title = name;
    (String(name).match(/^-*[^.-]*[.-]*|[^.-]+[.-]*/g) || []).forEach(function (part, i) { if (!part) return; if (i) e.appendChild(document.createElement('wbr')); e.appendChild(document.createTextNode(part)); });
    if (rest) e.appendChild(document.createTextNode(rest));
    return e;
  }
  function v(path) { return T[path] ? 'var(' + T[path].var + ')' : ''; }
  function val(path, mode) { var t = T[path]; return t ? (t.css[mode] || t.css.base) : ''; }
  function keys(prefix) { return Object.keys(T).filter(function (k) { return k.indexOf(prefix) === 0; }); }
  function store(k, value) { try { if (value == null) localStorage.removeItem(k); else localStorage.setItem(k, value); } catch { /* storage blocked: the setting still applies to this page */ } }
  function load(k) { try { return localStorage.getItem(k); } catch { return null; } }
  function press(nodes, on) { nodes.forEach(function (b) { b.setAttribute('aria-pressed', String(on(b))); }); }

  // ---------- theme ----------
  var themeButtons = all('[data-theme-choice]');
  function setTheme(choice) {
    if (choice === 'system') root.removeAttribute('data-theme'); else root.setAttribute('data-theme', choice);
    store('preview-theme', choice);
    press(themeButtons, function (b) { return b.getAttribute('data-theme-choice') === choice; });
  }
  var current = root.getAttribute('data-theme') || 'system';
  press(themeButtons, function (b) { return b.getAttribute('data-theme-choice') === current; });
  themeButtons.forEach(function (b) { b.addEventListener('click', function () { setTheme(b.getAttribute('data-theme-choice')); }); });

  // ---------- specimens ----------
  var sw = $('swatches');
  if (sw) keys('color.').filter(function (k) { return k.indexOf('color.data.') !== 0; }).forEach(function (k) {
    var card = el('div', 'swatch'), chip = el('div', 'chip'), meta = el('div', 'meta');
    if (k.indexOf('color.text.') === 0) {
      chip.textContent = 'Aa';
      chip.style.setProperty('color', v(k));
      chip.style.setProperty('background', v(k === 'color.text.inverse' ? 'color.surface.inverse' : 'color.surface.default'));
    } else if (k === 'color.focus') {
      chip.appendChild(el('span', 'ring-sample'));
    } else {
      chip.style.setProperty('background', v(k));
    }
    meta.appendChild(tok('strong', 'tok', k));
    meta.appendChild(el('span', null, val(k, 'light') + ' / ' + val(k, 'dark')));
    card.appendChild(chip); card.appendChild(meta); sw.appendChild(card);
  });

  function pairRow(p, ratioOf) {
    // Text pairings show text; "ui" pairings (3:1, non-text: borders, focus rings, chart marks) show a mark, because
    // text in a 3:1 color would be a real text-contrast failure on this page.
    var tr = el('tr'), td = el('td'), s;
    if (p.size === 'ui') {
      s = el('span', 'pair-sample');
      s.setAttribute('role', 'img'); s.setAttribute('aria-label', 'mark in ' + p.fg + ' on ' + p.bg);
      var mark = el('span', 'pair-mark'); mark.style.setProperty('background', v(p.fg)); s.appendChild(mark);
    } else {
      s = el('span', 'pair-sample', 'Aa');
      s.style.setProperty('color', v(p.fg));
    }
    s.style.setProperty('background', v(p.bg));
    td.appendChild(s); tr.appendChild(td);
    return ratioOf(tr);
  }
  function ratioCell(r, target) {
    if (r == null) return el('td', null, 'n/a');
    var ok = r >= target;
    return el('td', ok ? 'pass' : 'fail', r.toFixed(2) + ':1 ' + (ok ? 'pass' : 'FAIL'));
  }
  var tb = $('pairings');
  if (tb) (D.pairings || []).forEach(function (p) {
    tb.appendChild(pairRow(p, function (tr) {
      tr.appendChild(el('td', null, p.fg)); tr.appendChild(el('td', null, p.bg));
      tr.appendChild(el('td', null, p.target + ':1 (' + p.size + ')'));
      ['light', 'dark'].forEach(function (m) { tr.appendChild(ratioCell(p.ratio[m], p.target)); });
      return tr;
    }));
  });

  var ts = $('type-scale');
  if (ts) keys('font.size.').forEach(function (k) {
    var row = el('div', 'type-row');
    row.appendChild(el('span', 'label', k + ' · ' + val(k, 'base')));
    var s = el('p', 'sample', 'The quick brown fox jumps over the lazy dog');
    s.style.setProperty('font-size', v(k));
    if (/display|h1|h2|h3/.test(k)) s.style.setProperty('font-family', v('font.family.heading'));
    row.appendChild(s); ts.appendChild(row);
  });

  var ss = $('space-scale');
  if (ss) keys('space.').forEach(function (k) {
    var row = el('div', 'space-row'), bar = el('div', 'space-bar');
    bar.style.setProperty('inline-size', v(k));
    row.appendChild(bar); row.appendChild(tok('code', 'tok', k, ' · ' + val(k, 'base')));
    ss.appendChild(row);
  });

  var sh = $('shapes');
  if (sh) keys('radius.').concat(keys('shadow.')).forEach(function (k) {
    var b = tok('div', 'shape', k);
    if (k.indexOf('radius.') === 0) b.style.setProperty('border-radius', v(k));
    else { b.style.setProperty('box-shadow', v(k)); b.style.setProperty('border-radius', v('radius.md')); }
    sh.appendChild(b);
  });

  var bp = $('breakpoints');
  if (bp) keys('breakpoint.').concat(keys('viewport.')).forEach(function (k) {
    var li = el('li'); li.appendChild(tok('code', 'tok', k)); li.appendChild(document.createTextNode(' · ' + val(k, 'base')));
    bp.appendChild(li);
  });

  var tt = $('token-table');
  if (tt) Object.keys(T).forEach(function (k) {
    var tr = el('tr');
    tr.appendChild(tok('td', 'tok', k)); tr.appendChild(tok('td', 'tok', T[k].var));
    tr.appendChild(el('td', null, val(k, 'light'))); tr.appendChild(el('td', null, val(k, 'dark')));
    tt.appendChild(tr);
  });

  var ch = $('chart');
  var sample = [64, 41, 78, 52, 35, 80, 46, 59];   // illustrative values out of 100, labeled on the page
  if (ch) keys('color.data.').forEach(function (k, i) {
    var n = k.split('.').pop(), value = sample[i % sample.length];
    var li = el('li'), plot = el('div', 'plot'), bar = el('div', 'bar');
    plot.appendChild(el('span', 'value', String(value)));
    bar.style.setProperty('background', v(k));
    bar.style.setProperty('block-size', value + '%');
    bar.setAttribute('aria-hidden', 'true');
    plot.appendChild(bar); li.appendChild(plot);
    li.appendChild(el('span', 'series', 'S' + n));
    ch.appendChild(li);
  });

  // ---------- motion ----------
  function restart(n) { n.style.animationName = 'none'; void getComputedStyle(n).animationName; n.style.animationName = ''; }
  function replayComponents(scope) {
    // Replay the components' CSS animations (card entrance, badge pop-in, input shake). Under reduced motion
    // components.css allows only the short opacity fade on the card and badge (core §10), so that is all that replays.
    all('[data-component="card"][data-enter], [data-component="badge"], [data-component="input"][data-variant="error"] input', scope).forEach(restart);
  }
  var play = $('play-motion');
  if (play) play.addEventListener('click', function () {
    play.setAttribute('aria-pressed', String(play.getAttribute('aria-pressed') !== 'true'));
    all('#motion-tracks .motion-track').forEach(function (t) { t.classList.toggle('moved'); });
    replayComponents($('components') || document);
  });
  var replay = $('replay-motion');
  if (replay) replay.addEventListener('click', function () {
    // Jump the squares back to the start without a transition, then play them forward again.
    var tracks = all('.motion-track');
    tracks.forEach(function (t) { all('.mover', t).forEach(function (m) { m.style.transition = 'none'; }); t.classList.remove('moved'); });
    void document.body.offsetWidth;
    tracks.forEach(function (t) { all('.mover', t).forEach(function (m) { m.style.transition = ''; }); });
    requestAnimationFrame(function () {
      tracks.forEach(function (t) { t.classList.add('moved'); });
      if (play) play.setAttribute('aria-pressed', 'true');
      all('[data-play]').forEach(function (b) { b.setAttribute('aria-pressed', 'true'); });
    });
    replayComponents(document);
  });
  var reduce = $('toggle-reduce');
  if (reduce) {
    reduce.setAttribute('aria-pressed', String(root.getAttribute('data-motion') === 'reduce'));
    reduce.addEventListener('click', function () {
      var on = root.getAttribute('data-motion') !== 'reduce';
      if (on) root.setAttribute('data-motion', 'reduce'); else root.removeAttribute('data-motion');
      store('board-motion', on ? 'reduce' : null);
      reduce.setAttribute('aria-pressed', String(on));
    });
  }
  all('[data-play]').forEach(function (b) {
    b.addEventListener('click', function () {
      var pane = b.closest('.dir-pane') || document;
      b.setAttribute('aria-pressed', String(b.getAttribute('aria-pressed') !== 'true'));
      all('.motion-track', pane).forEach(function (t) { t.classList.toggle('moved'); });
      replayComponents(pane);
    });
  });

  // ---------- one mode's tokens on one element (side by side, studies) ----------
  function applyMode(node, vars, mode) {
    Object.keys(vars).forEach(function (name) { var c = vars[name]; node.style.setProperty(name, c[mode] != null ? c[mode] : c.base); });
    node.style.setProperty('color-scheme', mode);
  }
  function tokenVars() { var out = {}; Object.keys(T).forEach(function (k) { out[T[k].var] = T[k].css; }); return out; }

  // ---------- light and dark side by side ----------
  var duoBtn = $('toggle-duo'), duo = $('duo');
  function fillDuo() {
    var vars = tokenVars();
    all('.duo-pane', duo).forEach(function (pane) {
      var mode = pane.getAttribute('data-mode'), body = pane.querySelector('.duo-body');
      applyMode(pane, vars, mode);
      body.textContent = '';
      all('#board [data-duo]').forEach(function (tile) {
        var c = tile.cloneNode(true), pre = 'duo-' + mode + '-';
        // Keep ids unique: prefix every id and every reference to one.
        [c].concat(all('[id]', c)).forEach(function (n) { if (n.id) n.id = pre + n.id; });
        all('[for], [aria-describedby], [aria-labelledby], [aria-controls]', c).concat([c]).forEach(function (n) {
          ['for', 'aria-describedby', 'aria-labelledby', 'aria-controls'].forEach(function (a) {
            var x = n.getAttribute(a); if (x) n.setAttribute(a, x.split(/\s+/).map(function (r) { return pre + r; }).join(' '));
          });
        });
        all('.review, .anchor', c).forEach(function (n) { n.remove(); });
        c.removeAttribute('data-duo');
        c.setAttribute('inert', '');
        body.appendChild(c);
      });
    });
  }
  if (duoBtn && duo) duoBtn.addEventListener('click', function () {
    var on = duo.hidden;
    if (on) fillDuo();
    duo.hidden = !on;
    if (on) root.setAttribute('data-duo', 'on'); else root.removeAttribute('data-duo');
    duoBtn.setAttribute('aria-pressed', String(on));
  });

  // ---------- page or canvas layout, zoom, pan, minimap ----------
  var vp = $('board-viewport'), board = $('board'), mini = $('minimap'), level = $('zoom-level');
  var viewButtons = all('[data-view-choice]'), zoom = 1, MIN = 0.25, MAX = 2, STEP = 1.25;
  function canvasOn() { return root.getAttribute('data-view') === 'canvas' && vp && getComputedStyle(vp).overflowX === 'auto'; }
  function setView(choice) {
    if (choice === 'canvas') root.setAttribute('data-view', 'canvas'); else root.removeAttribute('data-view');
    store('board-view', choice === 'canvas' ? 'canvas' : null);
    press(viewButtons, function (b) { return b.getAttribute('data-view-choice') === choice; });
    drawMini();
  }
  press(viewButtons, function (b) { return b.getAttribute('data-view-choice') === (root.getAttribute('data-view') || 'page'); });
  viewButtons.forEach(function (b) { b.addEventListener('click', function () { setView(b.getAttribute('data-view-choice')); }); });

  function setZoom(z, keepCenter) {
    if (!vp) return;
    z = Math.min(MAX, Math.max(MIN, z));
    var cx = (vp.scrollLeft + vp.clientWidth / 2) / zoom, cy = (vp.scrollTop + vp.clientHeight / 2) / zoom;
    zoom = z;
    root.style.setProperty('--board-zoom', String(z));
    if (level) level.textContent = Math.round(z * 100) + '%';
    if (keepCenter !== false) { vp.scrollLeft = cx * z - vp.clientWidth / 2; vp.scrollTop = cy * z - vp.clientHeight / 2; }
    drawMini();
  }
  function fit() { if (!canvasOn()) return; var w = board.getBoundingClientRect().width / zoom; setZoom(vp.clientWidth / w, false); vp.scrollLeft = 0; vp.scrollTop = 0; drawMini(); }
  all('[data-zoom]').forEach(function (b) {
    b.addEventListener('click', function () {
      var k = b.getAttribute('data-zoom');
      if (k === 'in') setZoom(zoom * STEP); else if (k === 'out') setZoom(zoom / STEP); else fit();
    });
  });
  if (vp) {
    vp.addEventListener('keydown', function (e) {
      if (!canvasOn() || e.target !== vp || e.ctrlKey || e.metaKey || e.altKey) return;
      var k = e.key;
      if (k === '+' || k === '=') setZoom(zoom * STEP);
      else if (k === '-' || k === '_') setZoom(zoom / STEP);
      else if (k === '0') setZoom(1);
      else if (k === 'f' || k === 'F') fit();
      else return;
      e.preventDefault();
    });
    var drag = null;
    vp.addEventListener('pointerdown', function (e) {
      if (!canvasOn() || e.button !== 0 || e.target.closest('a, button, input, textarea, select, summary, label, .table-scroll, [contenteditable]')) return;
      drag = { x: e.clientX, y: e.clientY, l: vp.scrollLeft, t: vp.scrollTop, id: e.pointerId };
      vp.setPointerCapture(e.pointerId); vp.classList.add('panning');
    });
    vp.addEventListener('pointermove', function (e) {
      if (!drag || e.pointerId !== drag.id) return;
      vp.scrollLeft = drag.l - (e.clientX - drag.x); vp.scrollTop = drag.t - (e.clientY - drag.y);
    });
    function endDrag() { drag = null; vp.classList.remove('panning'); }
    vp.addEventListener('pointerup', endDrag); vp.addEventListener('pointercancel', endDrag);
    vp.addEventListener('wheel', function (e) {
      if (!canvasOn() || !(e.ctrlKey || e.metaKey)) return;
      e.preventDefault(); setZoom(e.deltaY < 0 ? zoom * STEP : zoom / STEP);
    }, { passive: false });
    vp.addEventListener('scroll', function () { drawMini(); }, { passive: true });
  }
  window.addEventListener('resize', function () { drawMini(); });

  function drawMini() {
    if (!mini || !board || !canvasOn()) return;
    var holder = mini.querySelector('.minimap-board'), view = mini.querySelector('.minimap-view');
    var b = board.getBoundingClientRect(), W = b.width, H = b.height;
    if (!W || !H) return;
    var s = Math.min(mini.clientWidth / W, mini.clientHeight / H);
    holder.textContent = '';
    all('.zone', board).forEach(function (z) {
      var r = z.getBoundingClientRect(), box = el('div', 'minimap-zone');
      box.style.left = ((r.left - b.left) * s) + 'px'; box.style.top = ((r.top - b.top) * s) + 'px';
      box.style.width = (r.width * s) + 'px'; box.style.height = (r.height * s) + 'px';
      holder.appendChild(box);
    });
    view.style.left = (vp.scrollLeft * s) + 'px'; view.style.top = (vp.scrollTop * s) + 'px';
    view.style.width = (Math.min(vp.clientWidth, W) * s) + 'px'; view.style.height = (Math.min(vp.clientHeight, H) * s) + 'px';
    mini.dataset.scale = String(s);
  }
  if (mini) mini.addEventListener('click', function (e) {
    var s = Number(mini.dataset.scale) || 1, r = mini.getBoundingClientRect();
    vp.scrollLeft = (e.clientX - r.left) / s - vp.clientWidth / 2; vp.scrollTop = (e.clientY - r.top) / s - vp.clientHeight / 2;
  });
  drawMini();
  // for the live board (lib/live.mjs): it keeps the zoom across a reload
  window.boardCanvas = { getZoom: function () { return zoom; }, setZoom: function (z) { setZoom(Number(z) || 1, false); } };

  // ---------- Phase 5 review (kept in this browser; download it as design-build/review.json) ----------
  var LABEL = { accept: 'Accepted', edit: 'Edit requested', reject: 'Rejected' };
  var reviewBtn = $('toggle-review'), saved = {};
  try { saved = JSON.parse(load('board-review') || '{}') || {}; } catch { saved = {}; }
  function today() { return new Date().toISOString().slice(0, 10); }
  function showVerdict(tile, rec) {
    var text = tile.querySelector('[data-verdict-text]');
    if (rec && rec.verdict) tile.setAttribute('data-verdict', rec.verdict); else tile.removeAttribute('data-verdict');
    press(all('.review [data-verdict]', tile), function (b) { return !!rec && b.getAttribute('data-verdict') === rec.verdict; });
    if (text) { text.hidden = !(rec && rec.verdict); text.textContent = rec && rec.verdict ? LABEL[rec.verdict] + (rec.note ? ': ' + rec.note : '') + (rec.date ? ' (' + rec.date + ')' : '') : ''; }
  }
  function verdicts() {
    var out = {};
    all('#board .tile[data-review-id]').forEach(function (tile) {
      var id = tile.getAttribute('data-review-id'), vv = tile.getAttribute('data-verdict');
      if (!vv) return;
      var note = tile.querySelector('.review .note');
      out[id] = { verdict: vv, note: note && note.value ? note.value : '', date: (saved[id] && saved[id].date) || today() };
    });
    return out;
  }
  all('#board .tile[data-review-id]').forEach(function (tile) {
    var id = tile.getAttribute('data-review-id'), note = tile.querySelector('.review .note');
    if (saved[id]) { if (note && saved[id].note != null) note.value = saved[id].note; showVerdict(tile, saved[id].verdict ? saved[id] : null); }
    all('.review [data-verdict]', tile).forEach(function (b) {
      b.addEventListener('click', function () {
        var k = b.getAttribute('data-verdict'), same = tile.getAttribute('data-verdict') === k;
        var rec = same ? { verdict: null, note: note ? note.value : '' } : { verdict: k, note: note ? note.value : '', date: today() };
        saved[id] = rec; store('board-review', JSON.stringify(saved));
        showVerdict(tile, rec.verdict ? rec : null);
      });
    });
    if (note) note.addEventListener('change', function () {
      var rec = saved[id] || { verdict: tile.getAttribute('data-verdict') || null };
      rec.note = note.value; saved[id] = rec; store('board-review', JSON.stringify(saved));
      if (rec.verdict) showVerdict(tile, rec);
    });
  });
  if (reviewBtn) {
    if (load('board-review-on') === 'on') { root.setAttribute('data-review', 'on'); reviewBtn.setAttribute('aria-pressed', 'true'); }
    reviewBtn.addEventListener('click', function () {
      var on = root.getAttribute('data-review') !== 'on';
      if (on) root.setAttribute('data-review', 'on'); else root.removeAttribute('data-review');
      store('board-review-on', on ? 'on' : null);
      reviewBtn.setAttribute('aria-pressed', String(on));
    });
  }
  var dl = $('download-review');
  if (dl) dl.addEventListener('click', function () {
    var data = { $comment: 'Phase 5 verdicts per board tile (design.md §16 Phase 5). Save as design-build/review.json, then re-run node design-build/board.mjs.', verdicts: verdicts() };
    var url = URL.createObjectURL(new Blob([JSON.stringify(data, null, 1) + '\n'], { type: 'application/json' }));
    var a = el('a'); a.href = url; a.download = 'review.json'; document.body.appendChild(a); a.click(); a.remove();
    setTimeout(function () { URL.revokeObjectURL(url); });
  });

  // ---------- Phase 3 studies: each direction's own tokens, per pane ----------
  if (page === 'studies') {
    var ids = (document.body.getAttribute('data-directions') || '').split(',').filter(Boolean), note = $('studies-note');
    if (location.protocol === 'file:') {
      if (note) { note.setAttribute('role', 'status'); note.textContent = 'Opened from a file, so the directions cannot load their tokens and every pane shows the current tokens. Run node design-build/board.mjs --serve --watch and open the address it prints.'; }
    } else Promise.all(ids.map(function (id) {
      return fetch('directions/' + encodeURIComponent(id) + '.resolved.json').then(function (r) { if (!r.ok) throw new Error(id + ': ' + r.status); return r.json(); }).then(function (d) {
        all('.dir-pane[data-direction="' + id + '"]').forEach(function (pane) {
          var mode = pane.getAttribute('data-mode'), body = pane.querySelector('[data-pairs]');
          applyMode(pane, d.vars || {}, mode);
          if (body) { body.textContent = ''; (d.pairings || []).forEach(function (p) {
            var tr = el('tr'); tr.appendChild(el('td', null, p.fg + ' on ' + p.bg)); tr.appendChild(ratioCell(p.ratio[mode], p.target)); body.appendChild(tr);
          }); }
        });
      });
    })).then(function () { if (note) note.textContent = 'Each direction is shown in light and dark with its own tokens.'; }, function (err) {
      if (note) { note.setAttribute('role', 'alert'); note.textContent = 'A direction did not load (' + err.message + '). Re-run node design-build/board.mjs --overview-only --direction <ID>.'; }
    });
  }
})();
